SELECT id, name AS customer_name
FROM customers
ORDER BY id;

SELECT id, total FROM orders
WHERE status = 'paid' AND total >= 50
ORDER BY id;

SELECT id, total FROM orders
ORDER BY total DESC, id ASC
LIMIT 2;

SELECT id, COALESCE(email, 'not supplied') AS contact
FROM customers WHERE email IS NULL
ORDER BY id;

SELECT c.id, c.name FROM customers AS c
WHERE EXISTS (
  SELECT 1 FROM orders AS o
  WHERE o.customer_id = c.id AND o.status = 'paid'
)
ORDER BY c.id;

WITH totals AS (
  SELECT customer_id, SUM(total) AS total
  FROM orders GROUP BY customer_id
)
SELECT customer_id, total FROM totals
WHERE total >= 50 ORDER BY customer_id;

SELECT customer_id, id,
  ROW_NUMBER() OVER (
    PARTITION BY customer_id ORDER BY total DESC, id
  ) AS position
FROM orders ORDER BY customer_id, position;

CREATE TABLE inventory (
  id INTEGER PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  quantity INTEGER NOT NULL CHECK (quantity >= 0)
);

BEGIN;
